      if (state.activeRound == null || !availableRoundIndexes.has(state.activeRound)) {
        state.activeRound = state.rounds.reduce((latest, round) => latest == null || round.round_index > latest ? round.round_index : latest, null);
      }
      if (state.activeRound != null) sessionStorage.setItem(activeRoundStorageKey, String(state.activeRound));
      if (state.expanded.size === 0 && state.activeRound != null) state.expanded.add('round:' + state.activeRound);
      els.status.classList.remove('is-visible'); renderExplorer();if(viewerIdentityChanged)renderPanes(); openReviewRoundReport();if(!initialPanelLoadStarted||roundBeforeLoad!==state.activeRound)refreshActivity();else if(renderActivityQueryStream.lastData)renderActivity(renderActivityQueryStream.lastData,state.activeRound);renderChat();initialPanelLoadStarted=true;
